// Construct a structurally valid RSA private key and attempt to recompute the private exponent d
// using the i15 backend. We enforce p,q odd with top bit set and p,q ≡ 3 (mod 4) as required.
// We exercise both the "length only" (d==NULL) path and the actual production path.
{
    // Choose moderate sizes for p and q for speed (32..64 bytes each)
    size_t plen = (size_t)(32 + (*FUZZ_PARAM(unsigned int) % 33));
    size_t qlen = (size_t)(32 + (*FUZZ_PARAM(unsigned int) % 33));

    // Generate p and q buffers; set MSB to ensure exact length; set LSB so value ≡ 3 (mod 4)
    std::string pbuf = FUZZ_PARAM_STR(); if (pbuf.size() < plen) pbuf.append(plen - pbuf.size(), (char)0xA1); pbuf.resize(plen);
    std::string qbuf = FUZZ_PARAM_STR(); if (qbuf.size() < qlen) qbuf.append(qlen - qbuf.size(), (char)0xA2); qbuf.resize(qlen);
    pbuf[0] = (unsigned char)(pbuf[0] | 0x80);
    qbuf[0] = (unsigned char)(qbuf[0] | 0x80);
    pbuf[plen - 1] = (unsigned char)((pbuf[plen - 1] & ~0x03) | 0x03);  // ensure ≡ 3 (mod 4)
    qbuf[qlen - 1] = (unsigned char)((qbuf[qlen - 1] & ~0x03) | 0x03);

    // Fill remaining CRT fields with non-null buffers (sizes similar to p/q)
    std::string dpbuf = FUZZ_PARAM_STR(); if (dpbuf.size() < plen) dpbuf.append(plen - dpbuf.size(), (char)0xB1); dpbuf.resize(plen);
    std::string dqbuf = FUZZ_PARAM_STR(); if (dqbuf.size() < qlen) dqbuf.append(qlen - dqbuf.size(), (char)0xB2); dqbuf.resize(qlen);
    std::string iqbuf = FUZZ_PARAM_STR(); size_t iqlen = qlen; if (iqbuf.size() < iqlen) iqbuf.append(iqlen - iqbuf.size(), (char)0xB3); iqbuf.resize(iqlen);

    // Program key fields; n_bitlen is nominal (plen+qlen)*8
    sk->n_bitlen = (uint32_t)((plen + qlen) * 8);
    sk->p = (unsigned char *)pbuf.data(); sk->plen = plen;
    sk->q = (unsigned char *)qbuf.data(); sk->qlen = qlen;
    sk->dp = (unsigned char *)dpbuf.data(); sk->dplen = plen;
    sk->dq = (unsigned char *)dqbuf.data(); sk->dqlen = qlen;
    sk->iq = (unsigned char *)iqbuf.data(); sk->iqlen = iqlen;

    // Choose a standard public exponent (odd > 1). 65537 reduces chances of sharing factors with (p-1),(q-1).
    uint32_t pubexp = 65537u;

    // First, query the length with d == NULL (may not detect all errors per API docs)
    size_t dlen_hint = br_rsa_i15_compute_privexp(NULL, sk, pubexp);

    // Prepare an output buffer: prefer hinted length when sensible; otherwise use modulus length as an upper bound
    size_t nbytes = (size_t)((sk->n_bitlen + 7) / 8);
    size_t out_len = (dlen_hint != 0 && dlen_hint <= nbytes) ? dlen_hint : nbytes;
    std::vector<unsigned char> dbuf(out_len);

    (void)br_rsa_i15_compute_privexp(dbuf.data(), sk, pubexp);

    // Validation summary: p,q constructed with MSB set and ≡3 mod 4; pubexp odd>1; both length-only and output paths executed; sk returned.
}

