import random
import string
from typing import List

# This generator produces a valid DNS hostname as bytes (C-string friendly)
# for use as SNI/hostname inputs. It focuses on ASCII labels (LDH rule),
# 1..63 chars per label, total length <= 253, no trailing dot, and NUL-terminated
# at the call site by the fuzzer. We therefore avoid embedding NUL here.
# We also vary structures to exercise edge cases (single-label, multi-label,
# near-limit label lengths, punycode-like prefixes, numeric-only, hyphen edge cases).

LDH = string.ascii_lowercase + string.digits + "-"
ALNUM = string.ascii_lowercase + string.digits


def _label(rng: random.Random, min_len: int = 1, max_len: int = 63,
           allow_hyphen_edges: bool = False) -> str:
    # Generate a single DNS label obeying LDH with no leading/trailing hyphen
    # unless explicitly allowed (to test edge acceptance by some libs that may reject them).
    L = rng.randint(min_len, max_len)
    if L == 1:
        return rng.choice(ALNUM)
    # Build middle characters freely, fix first/last to not be '-'
    middle_len = max(L - 2, 0)
    middle = "".join(rng.choice(LDH) for _ in range(middle_len))
    if allow_hyphen_edges and L >= 2 and rng.random() < 0.15:
        first = rng.choice(ALNUM + "-")
        last = rng.choice(ALNUM + "-")
        # Ensure not both ends hyphen to keep some variety
        if first == last == "-":
            last = rng.choice(ALNUM)
    else:
        first = rng.choice(ALNUM)
        last = rng.choice(ALNUM)
    return first + middle + last if L >= 2 else first


def _hostname_variants(rng: random.Random) -> str:
    # Choose a construction pattern to explore different valid shapes.
    choice = rng.randint(0, 9)

    if choice == 0:
        # Simple two-label domain
        return _label(rng, 3, 10) + "." + _label(rng, 2, 6)
    if choice == 1:
        # Three-label domain with shorter TLD-like ending
        return ".".join([
            _label(rng, 1, 20),
            _label(rng, 1, 15),
            _label(rng, 2, 6)
        ])
    if choice == 2:
        # Single label (valid per RFC 1123 for hostnames in some contexts)
        return _label(rng, 1, 63)
    if choice == 3:
        # Many labels, small each
        parts = [_label(rng, 1, 5) for _ in range(rng.randint(4, 10))]
        name = ".".join(parts)
        return name[:253]  # ensure overall limit
    if choice == 4:
        # Label near 63 chars
        l1 = _label(rng, 60, 63)
        l2 = _label(rng, 2, 6)
        name = l1 + "." + l2
        return name[:253]
    if choice == 5:
        # Numeric-looking labels
        parts = [
            str(rng.randint(0, 999999)).rjust(rng.randint(1, 6), "0"),
            str(rng.randint(0, 9999)),
            _label(rng, 2, 6)
        ]
        return ".".join(parts)
    if choice == 6:
        # Hyphen heavy middle (but not at edges)
        core = "-" * rng.randint(1, 10)
        prefix = _label(rng, 1, 10)
        suffix = _label(rng, 1, 10)
        l1 = (prefix[0] + core + suffix[-1])[:rng.randint(3, 20)]
        # Fix edges to alnum just in case
        if l1[0] == "-":
            l1 = "a" + l1[1:]
        if l1[-1] == "-":
            l1 = l1[:-1] + "z"
        return l1 + "." + _label(rng, 2, 6)
    if choice == 7:
        # Punycode-like prefix
        l1 = "xn--" + _label(rng, 1, 50)
        # Ensure no trailing hyphen
        if l1[-1] == "-":
            l1 = l1[:-1] + "a"
        return l1[:63] + "." + _label(rng, 2, 6)
    if choice == 8:
        # Long multi-label up to overall limit
        parts: List[str] = []
        total = 0
        while True:
            lab = _label(rng, 1, 15)
            add = (1 if parts else 0) + len(lab)  # dot + label
            if total + add > 253:
                break
            parts.append(lab)
            total += add
            if rng.random() < 0.2 and len(parts) >= 2:
                break
        return ".".join(parts)
    # choice == 9
    # Shortest forms and edge label lengths
    first = _label(rng, 1, 1)
    mid = _label(rng, 2, 63)
    last = _label(rng, 2, 6)
    return ".".join([first, mid, last])[:253]


def _sanitize(name: str) -> str:
    # Ensure ASCII lowercase, strip accidental dots at ends, trim length
    name = name.lower()
    name = name.strip('.')
    # Remove any disallowed characters just in case (keep LDH and dots)
    filtered = []
    for ch in name:
        if ch in LDH or ch == '.':
            filtered.append(ch)
        elif ch in string.ascii_uppercase:
            filtered.append(ch.lower())
        elif ch in string.digits:
            filtered.append(ch)
        # ignore others
    name = ''.join(filtered)
    # Enforce label rules: no empty labels due to consecutive dots
    parts = [p for p in name.split('.') if len(p) > 0]
    if not parts:
        parts = ["localhost"]
    # Fix labels that start/end with '-' or exceed 63
    fixed_parts = []
    for p in parts:
        if not p:
            p = "a"
        if p[0] == '-':
            p = 'a' + p[1:]
        if p and p[-1] == '-':
            p = p[:-1] + 'a'
        if len(p) > 63:
            p = p[:63]
        fixed_parts.append(p if p else 'a')
    name = '.'.join(fixed_parts)
    if len(name) > 253:
        name = name[:253]
        name = name.rstrip('.')
    if not name:
        name = 'localhost'
    return name


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    name = _hostname_variants(rng)
    name = _sanitize(name)
    # Return as bytes without a trailing NUL; fuzzer stub appends NUL itself.
    return name.encode('ascii', errors='ignore')

import random
import struct
import time

# Generate valid unencrypted PKCS#8 OneAsymmetricKey (DER) for RSA or EC.
# We handcraft minimal ASN.1 encodings for:
# - RSA private key in PKCS#1 inside PKCS#8 with rsaEncryption OID
# - EC private key in SEC1 inside PKCS#8 with id-ecPublicKey OID and named curve
# The outputs are valid DER sequences suitable for br_skey_decoder_push.

# ASN.1 helpers
def der_len(l):
    if l < 0x80:
        return bytes([l])
    s = []
    while l > 0:
        s.append(l & 0xFF)
        l >>= 8
    s.reverse()
    return bytes([0x80 | len(s)]) + bytes(s)

def der_integer(b: bytes, signed=False):
    # Ensure minimal two's complement for INTEGER
    if len(b) == 0:
        b = b"\x00"
    # Strip leading zeros
    i = 0
    while i + 1 < len(b) and b[i] == 0:
        i += 1
    b = b[i:]
    if not signed:
        # If MSB set, prepend 0x00 to indicate positive
        if b[0] & 0x80:
            b = b"\x00" + b
    return bytes([0x02]) + der_len(len(b)) + b

def der_octet_string(b: bytes):
    return bytes([0x04]) + der_len(len(b)) + b

def der_bit_string(b: bytes):
    # Add 0 unused bits count byte (0)
    return bytes([0x03]) + der_len(len(b) + 1) + b"\x00" + b

def der_null():
    return b"\x05\x00"

def der_object_identifier(oid):
    # oid: tuple of ints
    if len(oid) < 2:
        raise ValueError("OID too short")
    first = 40 * oid[0] + oid[1]
    body = [first]
    for v in oid[2:]:
        # base-128 varint
        stack = [v & 0x7F]
        v >>= 7
        while v:
            stack.append(0x80 | (v & 0x7F))
            v >>= 7
        body.extend(reversed(stack))
    b = bytes(body)
    return bytes([0x06]) + der_len(len(b)) + b

def der_sequence(*elts: bytes):
    content = b"".join(elts)
    return bytes([0x30]) + der_len(len(content)) + content

def der_context_specific(idx: int, value: bytes, constructed=True):
    tag = 0xA0 + idx if constructed else 0x80 + idx
    return bytes([tag]) + der_len(len(value)) + value

# OIDs
OID_rsaEncryption = (1, 2, 840, 113549, 1, 1, 1)
OID_id_ecPublicKey = (1, 2, 840, 10045, 2, 1)
OID_secp256r1 = (1, 2, 840, 10045, 3, 1, 7)

# Simple deterministic big integer helpers

def randbits(rng, nbits):
    nbytes = (nbits + 7) // 8
    b = bytes(rng.getrandbits(8) for _ in range(nbytes))
    # Force exact bit length
    mask = 0xFF >> ((8 - (nbits % 8)) % 8)
    if mask == 0:
        mask = 0xFF
    if nbytes:
        b = bytes([b[0] & mask]) + b[1:]
        # Ensure top bit set
        topbit = 1 << ((nbits - 1) % 8)
        b = bytes([b[0] | topbit]) + b[1:]
    return b

# Very lightweight RSA key generation (toy, not cryptographically correct primes). 
# We do not need valid primes for decoding; PKCS#8 decoder will accept structure.
# To increase validity for downstream code, we attempt to build consistent CRT params
# from randomly generated p and q as odd numbers and compute dp, dq, iq.

def egcd(a, b):
    if b == 0:
        return (1, 0, a)
    x1, y1, g = egcd(b, a % b)
    return (y1, x1 - (a // b) * y1, g)

def modinv(a, m):
    x, y, g = egcd(a, m)
    if g != 1:
        return None
    return x % m

def int_from_bytes(b):
    return int.from_bytes(b, 'big')

def int_to_bytes(x, length=None):
    if x == 0:
        b = b"\x00"
    else:
        blen = (x.bit_length() + 7) // 8
        b = x.to_bytes(blen, 'big')
    if length is not None:
        b = b.rjust(length, b"\x00")
    return b

def gen_rsa_pkcs1_der(rng, bits=512):
    # generate two random odd numbers of half size; retry to avoid equality
    half = bits // 2
    def rand_odd(nbits):
        b = randbits(rng, nbits)
        return int_from_bytes(b) | 1
    p = rand_odd(half)
    q = rand_odd(half)
    # ensure p != q
    for _ in range(10):
        if p != q:
            break
        q = rand_odd(half)
    n = p * q
    phi = (p - 1) * (q - 1)
    e = 65537
    # ensure e coprime to phi; if not, tweak p
    for _ in range(5):
        if phi % e != 0:
            break
        p = rand_odd(half)
        n = p * q
        phi = (p - 1) * (q - 1)
    d = modinv(e, phi)
    if d is None:
        d = 3  # fallback to keep structure
    dp = d % (p - 1) if p > 2 else 1
    dq = d % (q - 1) if q > 2 else 1
    iq = modinv(q, p)
    if iq is None:
        iq = 1
    # Encode PKCS#1 RSAPrivateKey:
    # RSAPrivateKey ::= SEQUENCE { version INTEGER(0), n, e, d, p, q, dp, dq, iq }
    elems = [
        der_integer(b"\x00"),
        der_integer(int_to_bytes(n)),
        der_integer(int_to_bytes(e)),
        der_integer(int_to_bytes(d)),
        der_integer(int_to_bytes(p)),
        der_integer(int_to_bytes(q)),
        der_integer(int_to_bytes(dp)),
        der_integer(int_to_bytes(dq)),
        der_integer(int_to_bytes(iq)),
    ]
    return der_sequence(*elems)

# Minimal EC private key (SEC1) for secp256r1
# We generate a 32-byte random scalar; not validated on curve but acceptable for decoding.

def gen_ec_sec1_der(rng):
    # ECPrivateKey ::= SEQUENCE { version INTEGER 1, privateKey OCTET STRING (32), parameters [0] ECParameters (namedCurve), publicKey [1] BIT STRING OPTIONAL }
    version = der_integer(b"\x01")
    x = bytes(rng.getrandbits(8) for _ in range(32))
    priv = der_octet_string(x)
    params = der_context_specific(0, der_object_identifier(OID_secp256r1))
    # omit publicKey to keep it minimal
    return der_sequence(version, priv, params)

# Build AlgorithmIdentifier

def algo_id(oid, params=None):
    if params is None:
        params = der_null()
    return der_sequence(der_object_identifier(oid), params)

# Wrap private key in PKCS#8 OneAsymmetricKey

def wrap_pkcs8(private_key_der: bytes, alg_oid, alg_params=None):
    # OneAsymmetricKey ::= SEQUENCE { version INTEGER(0), algorithm AlgorithmIdentifier, privateKey OCTET STRING, attributes [0] OPTIONAL }
    version = der_integer(b"\x00")
    aid = algo_id(alg_oid, alg_params)
    pk = der_octet_string(private_key_der)
    return der_sequence(version, aid, pk)


def gen_pkcs8_rsa(rng):
    # rsaEncryption with NULL params
    pkcs1 = gen_rsa_pkcs1_der(rng, bits=rng.choice([512, 768, 1024]))
    return wrap_pkcs8(pkcs1, OID_rsaEncryption, der_null())


def gen_pkcs8_ec(rng):
    sec1 = gen_ec_sec1_der(rng)
    # id-ecPublicKey with namedCurve parameter
    params = der_object_identifier(OID_secp256r1)
    return wrap_pkcs8(sec1, OID_id_ecPublicKey, params)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    choice = rng.random()
    if choice < 0.5:
        return gen_pkcs8_rsa(rng)
    else:
        return gen_pkcs8_ec(rng)
